import { useCallback, useMemo } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';
import { useSelector } from 'react-redux';

import {
  FilterAlertManager,
  PageHeader,
  StickyScrollWithFilters,
} from 'components';
import {
  StickyNavigationTopOffsetProvider,
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterManagement,
  usePageFilterStatus,
  useRelatedAnalysisContextBanner,
} from 'hooks';
import { BrandPowerContextBanner } from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/components/BrandPowerContextBanner';
import { RootState } from 'redux/store';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';
import { boldRichTextValues } from 'utils/i18n/richTextValues';

import { KpiSwitch } from './components/KpiSwitch/KpiSwitch';
import {
  PERFORMANCE_TOOL_FILTER_CATEGORIES,
  PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
  PERFORMANCE_TOOL_NAVIGATION_TEST_ID,
  PERFORMANCE_TOOL_PAGE_NAME,
  PERFORMANCE_TOOL_VISIBLE_FILTER_FIELDS,
  WATERFALL_RESET_EVENT,
} from './constants';
import {
  MARKET_SHARE_TIME_PERIOD_ALERT_KEY,
  useMarketShareTimePeriodAlert,
} from './hooks/useMarketShareAlert/useMarketShareTimePeriodAlert';
import { useMarketShareWeightTypeAlert } from './hooks/useMarketShareAlert/useMarketShareWeightTypeAlert';
import { getPageSubtitleByKpi, getPageTitleByKpi } from './utils';

export const PerformanceTool: React.FC = () => {
  const { currentPage } = useCurrentPage();
  const { formatMessage } = useIntl();
  const showRelatedAnalysisBanner =
    useRelatedAnalysisContextBanner('brand-power');
  const { applied } = usePageFilterApplied(currentPage);
  const { isLoading: isFilterLoading, isLoaded: isFilterLoaded } =
    usePageFilterStatus(currentPage);
  const { isOpen: isMarketShareAlertOpen, close: closeMarketShareAlert } =
    useMarketShareWeightTypeAlert(
      applied,
      currentPage === PERFORMANCE_TOOL_PAGE_NAME &&
        isFilterLoaded &&
        !isFilterLoading &&
        applied.zone != null &&
        applied.country != null,
      true,
    );

  const { closeTimePeriodAlert, isTimePeriodAlertOpen } =
    useMarketShareTimePeriodAlert(
      applied,
      currentPage === PERFORMANCE_TOOL_PAGE_NAME &&
        isFilterLoaded &&
        !isFilterLoading &&
        applied.zone != null &&
        applied.country != null,
      true,
    );
  const {
    updateForm,
    apply,
    dismissTimePeriodFallback,
    returnToPreviousKpi,
    dismissAlertFallback,
    restoreAlertFallback,
  } = usePageFilterManagement(PERFORMANCE_TOOL_PAGE_NAME);

  const pageTitle = useMemo(
    () => formatMessage({ id: getPageTitleByKpi(applied.kpis as string) }),
    [applied.kpis, formatMessage],
  );

  const handleFilterChange = (key: string, value: string) => {
    updateForm(key, value);
    apply();
  };

  const handleFilterReset = useCallback(() => {
    globalThis.dispatchEvent(new Event(WATERFALL_RESET_EVENT));
  }, []);

  const fallback = useSelector(
    (state: RootState) =>
      state.filters.pages[PERFORMANCE_TOOL_PAGE_NAME]
        ?.performanceToolTimePeriodFallback,
  );
  return (
    <>
      <FilterAlertManager
        pageName={PERFORMANCE_TOOL_PAGE_NAME}
        currentPage={currentPage}
        applied={applied}
        isLoaded={isFilterLoaded}
        isLoading={isFilterLoading}
        alerts={[
          {
            key: 'market-share-weight-type',
            type: 'info',
            isOpen: isMarketShareAlertOpen,
            title: formatMessage({
              id: 'ValueCreation.PerformanceTool.market_share_official.systemNotifications.weightTypeChanged.title',
            }),
            message: formatMessage({
              id: 'ValueCreation.PerformanceTool.market_share_official.systemNotifications.weightTypeChanged.message',
            }),
            closeButtonLabel: formatMessage({
              id: 'ValueCreation.PerformanceTool.market_share_official.systemNotifications.weightTypeChanged.closeAction',
            }),
            onClose: closeMarketShareAlert,
            suppressInitial: false,
          },
          {
            key: 'kpi-time-period',
            isOpen: Boolean(fallback),
            title: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.title',
            }),
            message: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.message',
            }),
            closeButtonLabel: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.closeAction',
            }),
            actionMessage: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.returnAction',
            }),
            onAction: returnToPreviousKpi,
            onClose: () => {
              dismissTimePeriodFallback();
              closeTimePeriodAlert();
            },
          },
          {
            key: MARKET_SHARE_TIME_PERIOD_ALERT_KEY,
            isOpen: isTimePeriodAlertOpen,
            title: formatMessage({
              id: 'ValueCreation.PerformanceTool.market_share_official.systemNotifications.timePeriodChanged.title',
            }),
            message: formatMessage({
              id: 'ValueCreation.PerformanceTool.market_share_official.systemNotifications.timePeriodChanged.message',
            }),
            closeButtonLabel: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.closeAction',
            }),
            actionMessage: formatMessage({
              id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.returnAction',
            }),
            onAction: () =>
              restoreAlertFallback(MARKET_SHARE_TIME_PERIOD_ALERT_KEY),
            onClose: () => {
              dismissAlertFallback(MARKET_SHARE_TIME_PERIOD_ALERT_KEY);
              closeTimePeriodAlert();
            },
          },
        ]}
      />
      <StickyScrollWithFilters
        filter={{
          pageName: PERFORMANCE_TOOL_PAGE_NAME,
          visibleFields: PERFORMANCE_TOOL_VISIBLE_FILTER_FIELDS,
          maxVisibleFilters: PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
          onReset: handleFilterReset,
          filterCategories:
            PERFORMANCE_TOOL_FILTER_CATEGORIES['market_share'] || [],
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/performance-tool',
              pageName: 'Performance Tool',
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
        dataTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      />

      <StickyNavigationTopOffsetProvider
        navigationTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      >
        <StyledGridContainer $isResponsivePage>
          <StyledHomeContainer>
            <PageHeader
              title={pageTitle}
              subtitle={
                <FormattedMessage
                  id={getPageSubtitleByKpi(applied.kpis as string)}
                  values={
                    boldRichTextValues as unknown as Record<
                      string,
                      React.ReactNode
                    >
                  }
                />
              }
              loading={isFilterLoading}
            />

            {showRelatedAnalysisBanner && (
              <BrandPowerContextBanner
                title={formatMessage({
                  id: 'ValueCreation.PerformanceTool.contextBanner.fromBrandPower.title',
                  defaultMessage:
                    'Performance Tool opened with Brand Power context',
                })}
                message={formatMessage({
                  id: 'ValueCreation.PerformanceTool.contextBanner.fromBrandPower.message',
                  defaultMessage:
                    'Power KPI and current country were preserved to make navigation context clear.',
                })}
                duration={6000}
              />
            )}
            <KpiSwitch
              kpi={applied.kpis as string}
              onFilterChange={handleFilterChange}
            />
          </StyledHomeContainer>
        </StyledGridContainer>
      </StickyNavigationTopOffsetProvider>
    </>
  );
};
